                float4 screenPos : TEXCOORD1;
                float2 localPos : TEXCOORD2;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            float Snap(float v, float snapSize)
            {
                return snapSize > 0 ? floor(v / snapSize + 0.5) * snapSize : v;
            }

            v2f vert(appdata v)
            {
                v2f o;
                UNITY_SETUP_INSTANCE_ID(v);
                UNITY_TRANSFER_INSTANCE_ID(v, o);
                o.vertex = TransformObjectToHClip(v.vertex.xyz);
                o.uv = v.uv;
                o.color = v.color * _Color;
                o.screenPos = ComputeScreenPos(o.vertex);
                // Local position for mesh-edge detection
                o.localPos = v.vertex.xy;
                return o;
            }

            half4 SampleWater(float2 uv, float time)
            {
                float2 scrollUV = uv;
                float sx = Snap(_ScrollX * time, _PixelSnap * 0.5);
                float sy = Snap(_ScrollY * time, _PixelSnap * 0.5);
                scrollUV.x += sx;
                scrollUV.y += sy;
                float waveOffset = sin(Snap(uv.x * 6.2831, _PixelSnap) + Snap(_WaveFrequency * time, _PixelSnap * 0.5)) * _WaveAmplitude;
                scrollUV.y += waveOffset;
                return SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, scrollUV);
            }

            // Detect UV-space edges using screen-space derivatives
            float DetectUVEdge(float2 uv)
            {
                // Screen-space derivatives tell us how fast UV changes per pixel
                float2 dx = ddx(uv);
                float2 dy = ddy(uv);

                // Sample neighbors in screen-space
                float2 uvRight = uv + dx * _EdgeWidth;
                float2 uvUp    = uv + dy * _EdgeWidth;
                float2 uvLeft  = uv - dx * _EdgeWidth;
                float2 uvDown  = uv - dy * _EdgeWidth;

                // Check if neighbor UVs are still in [0,1] range (inside the mesh)
                // Pixels near the mesh border will have neighbors that wrap or go out of bounds
                float edgeH = step(0.0, uvLeft.x) * step(uvLeft.x, 1.0) *
                               step(0.0, uvLeft.y) * step(uvLeft.y, 1.0);
                float edgeHR = step(0.0, uvRight.x) * step(uvRight.x, 1.0) *
                                step(0.0, uvRight.y) * step(uvRight.y, 1.0);
                float edgeV = step(0.0, uvUp.x) * step(uvUp.x, 1.0) *
                               step(0.0, uvUp.y) * step(uvUp.y, 1.0);
                float edgeVD = step(0.0, uvDown.x) * step(uvDown.x, 1.0) *
                                step(0.0, uvDown.y) * step(uvDown.y, 1.0);

                // Also detect proximity to UV border (0 or 1)
                float2 absDist = min(uv, 1.0 - uv);
                float borderDist = min(absDist.x, absDist.y);
                float borderEdge = 1.0 - smoothstep(0.0, _EdgeWidth, borderDist);

                // Compare with neighbor validity
                float neighborEdge = (1.0 - edgeH) + (1.0 - edgeHR) + (1.0 - edgeV) + (1.0 - edgeVD);
                neighborEdge = saturate(neighborEdge);

                return max(neighborEdge, borderEdge);
            }

            // Detect edges in the submersion mask
            float DetectMaskEdge(float2 screenUV)
            {
                float2 texel = _SubmersionMask_TexelSize.xy * _IntersectWidth;
                float c = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV).a;
                float r = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV + float2(texel.x, 0)).a;
                float l = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV - float2(texel.x, 0)).a;
                float u = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV + float2(0, texel.y)).a;
                float d = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV - float2(0, texel.y)).a;

                float gx = r - l;
                float gy = u - d;
                float edge = sqrt(gx * gx + gy * gy);

                float minN = min(min(r, l), min(u, d));
                float borderEdge = c > 0.01 && minN < 0.01 ? 1.0 : 0.0;

                return saturate(max(edge, borderEdge));
            }

            half4 frag(v2f i) : SV_Target
            {
                half4 water = SampleWater(i.uv, _Time.y) * i.color;

                // Edge outline (UV border detection)
                float edgeMask = DetectUVEdge(i.uv);
                half3 finalColor = lerp(water.rgb, _EdgeColor.rgb, edgeMask * _EdgeColor.a);

                // Intersection outline
                float2 screenUV = i.screenPos.xy / i.screenPos.w;
                float maskEdge = DetectMaskEdge(screenUV);
                finalColor = lerp(finalColor, _IntersectColor.rgb, maskEdge * _IntersectColor.a * 0.7);

                // Submersion tint
                float maskVal = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV).a;
                finalColor = lerp(finalColor, _IntersectColor.rgb * 0.5, maskVal * 0.3);

                // Posterize for pixel art
                float lum = dot(finalColor, float3(0.2126, 0.7152, 0.0722));
                float steps = max(2.0, _PosterizeSteps);
                float posterLum = floor(lum * steps + 0.5) / steps;
                half3 rampColor = SAMPLE_TEXTURE2D(_ColorRamp, sampler_ColorRamp, float2(posterLum, 0.5)).rgb;
                finalColor = lerp(finalColor, rampColor, 0.2);

                half4 result;
                result.rgb = finalColor;
                result.a = water.a * i.color.a;
                result.rgb *= result.a;
                return result;
            }
            ENDHLSL
        }

        // Pass 2: Fallback for non-2D light modes (mesh renderers, scene view)
        Pass
        {
            Name "WaterFallback"
            Tags { "LightMode" = "SRPDefaultUnlit" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 2.0
            #pragma multi_compile_instancing

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);
            float4 _MainTex_TexelSize;
            half4 _Color;
            float _ScrollX;
            float _ScrollY;
            float _WaveAmplitude;
            float _WaveFrequency;
            float _PixelSnap;
            half4 _EdgeColor;
            float _EdgeWidth;
            float _EdgeThreshold;
            TEXTURE2D(_SubmersionMask);
            SAMPLER(sampler_SubmersionMask);
            float4 _SubmersionMask_TexelSize;
            half4 _IntersectColor;
            float _IntersectWidth;
            float _PosterizeSteps;
            TEXTURE2D(_ColorRamp);
            SAMPLER(sampler_ColorRamp);

            struct appdata
            {
                float4 vertex : POSITION;
                float4 color : COLOR;
                float2 uv : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            struct v2f
            {
                float4 vertex : SV_POSITION;
                half4 color : COLOR;
                float2 uv : TEXCOORD0;
                float4 screenPos : TEXCOORD1;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            float Snap(float v, float snapSize)
            {
                return snapSize > 0 ? floor(v / snapSize + 0.5) * snapSize : v;
            }

            v2f vert(appdata v)
            {
                v2f o;
                UNITY_SETUP_INSTANCE_ID(v);
                UNITY_TRANSFER_INSTANCE_ID(v, o);
                o.vertex = TransformObjectToHClip(v.vertex.xyz);
                o.uv = v.uv;
                o.color = v.color * _Color;
                o.screenPos = ComputeScreenPos(o.vertex);
                return o;
            }

            half4 frag(v2f i) : SV_Target
            {
                float2 scrollUV = i.uv;
                float sx = Snap(_ScrollX * _Time.y, _PixelSnap * 0.5);
                float sy = Snap(_ScrollY * _Time.y, _PixelSnap * 0.5);
                scrollUV.x += sx;
                scrollUV.y += sy;
                float waveOffset = sin(Snap(i.uv.x * 6.2831, _PixelSnap) + Snap(_WaveFrequency * _Time.y, _PixelSnap * 0.5)) * _WaveAmplitude;
                scrollUV.y += waveOffset;

                half4 water = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, scrollUV) * i.color;

                // Edge detection using UV border proximity
                float2 absDist = min(i.uv, 1.0 - i.uv);
                float borderDist = min(absDist.x, absDist.y);
                float edgeMask = 1.0 - smoothstep(0.0, _EdgeWidth, borderDist);

                half3 finalColor = lerp(water.rgb, _EdgeColor.rgb, edgeMask * _EdgeColor.a);

                // Intersection
                float2 screenUV = i.screenPos.xy / i.screenPos.w;
                float2 texel = _SubmersionMask_TexelSize.xy * _IntersectWidth;
                float c = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV).a;
                float r = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV + float2(texel.x, 0)).a;
                float l = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV - float2(texel.x, 0)).a;
                float u = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV + float2(0, texel.y)).a;
                float d = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV - float2(0, texel.y)).a;
                float gx = r - l;
                float gy = u - d;
                float maskEdge = saturate(sqrt(gx * gx + gy * gy));
                float minN = min(min(r, l), min(u, d));
                maskEdge = max(maskEdge, c > 0.01 && minN < 0.01 ? 1.0 : 0.0);

                finalColor = lerp(finalColor, _IntersectColor.rgb, maskEdge * _IntersectColor.a * 0.7);
                float maskVal = SAMPLE_TEXTURE2D(_SubmersionMask, sampler_SubmersionMask, screenUV).a;
                finalColor = lerp(finalColor, _IntersectColor.rgb * 0.5, maskVal * 0.3);

                // Posterize
                float lum = dot(finalColor, float3(0.2126, 0.7152, 0.0722));
                float steps = max(2.0, _PosterizeSteps);
                float posterLum = floor(lum * steps + 0.5) / steps;
                half3 rampColor = SAMPLE_TEXTURE2D(_ColorRamp, sampler_ColorRamp, float2(posterLum, 0.5)).rgb;
                finalColor = lerp(finalColor, rampColor, 0.2);

                half4 result;
                result.rgb = finalColor;
                result.a = water.a * i.color.a;
                result.rgb *= result.a;
                return result;
            }
            ENDHLSL
        }
    }
    Fallback "Sprites/Default"
}

Shader "Flynn/ProjectedShadow"
{
    // Flat ground-cast silhouette shadow for billboarded 2.5D sprites.
    // The shadow quad is laid flat on the XZ ground by ShadowManager and given
    // the target's live sprite texture; this shader stamps it as a uniform dark
    // silhouette (ignoring the sprite's RGB).
    //
    // Projection model: a camera-facing sprite cast onto the ground by a
    // directional sun is an affine map — rotate to the sun's ground azimuth,
    // stretch by elevation, AND shear (lateral offsets stay along camera-right
    // while height projects along the azimuth). ShadowManager feeds the shear
    // terms per renderer; the vertex stage applies them so the base stays
    // pinned at the contact point and the silhouette leans away from the sun.
    // The fragment stage grows a penumbra blur and alpha falloff toward the
    // cast tip and darkens the contact end so objects feel grounded.
    Properties
    {
        [PerRendererData] _MainTex ("Sprite Texture", 2D) = "white" {}
        _ShadowColor ("Shadow Color", Color) = (0.16, 0.21, 0.32, 0.55)
        _Opacity ("Opacity", Range(0, 1)) = 1
        _TipFade ("Tip Fade (toward head)", Range(0, 1)) = 0.35
        _AlphaCutoff ("Alpha Cutoff", Range(0, 1)) = 0.1
        _PenumbraScale ("Penumbra Scale (UV blur at tip)", Range(0, 0.05)) = 0.012
        _ContactBoost ("Contact Darkening", Range(0, 1)) = 0.35
    }

    SubShader
    {
        Tags
        {
            "RenderPipeline" = "UniversalPipeline"
            "Queue" = "Transparent"
            "IgnoreProjector" = "True"
            "RenderType" = "Transparent"
            "PreviewType" = "Plane"
            "CanUseSpriteAtlas" = "True"
        }

        Cull Off
        ZWrite Off
        Blend One OneMinusSrcAlpha

        Pass
        {
            Name "Default"
            Tags { "LightMode" = "UniversalForward" }

        HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 2.0
            #pragma multi_compile_instancing

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            struct appdata
            {
                float4 vertex : POSITION;
                float4 color : COLOR;
                float2 uv : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            struct v2f
            {
                float4 vertex : SV_POSITION;
                half4 color : COLOR;
                float2 uv : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);

            CBUFFER_START(UnityPerMaterial)
                half4 _ShadowColor;
                float _Opacity;
                float _TipFade;
                float _AlphaCutoff;
                float _PenumbraScale;
                float _ContactBoost;
            CBUFFER_END

            // Per-renderer values from ShadowManager via MaterialPropertyBlock.
            // _ShearAmt/_LatScale: shear terms in sprite-local space (sin/cos of the
            // angle between camera-right and the quad's lateral axis, length-corrected).
            // _SpriteVMin/_SpriteVInvH: map atlas UV.y to a 0..1 base→tip coordinate.
            // _ShadowStretch: sun-elevation length factor, scales penumbra growth.
            float _ShearAmt;
            float _LatScale;
            float _SpriteVMin;
            float _SpriteVInvH;
            float _ShadowStretch;

            v2f vert(appdata v)
            {
                v2f o;
                UNITY_SETUP_INSTANCE_ID(v);
                UNITY_TRANSFER_INSTANCE_ID(v, o);

                float2 p = v.vertex.xy;
                v.vertex.x = p.x * _LatScale;
                v.vertex.y = p.y + p.x * _ShearAmt;

                o.vertex = TransformObjectToHClip(v.vertex.xyz);
                o.uv = v.uv;
                o.color = v.color;
                return o;
            }

            half SampleSilhouette(float2 uv, float radius)
            {
                // 5-tap cross blur; radius grows toward the tip (penumbra widening).
                half a = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv).a * 0.4h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2( radius, 0)).a * 0.15h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2(-radius, 0)).a * 0.15h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2(0,  radius)).a * 0.15h;
                a += SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, uv + float2(0, -radius)).a * 0.15h;
                return a;
            }

            half4 frag(v2f i) : SV_Target
            {
                UNITY_SETUP_INSTANCE_ID(i);

                // 0 at the contact point, 1 at the cast tip — atlas-safe.
                float h01 = saturate((i.uv.y - _SpriteVMin) * _SpriteVInvH);

                float radius = _PenumbraScale * h01 * max(_ShadowStretch, 1.0);
                half texA = SampleSilhouette(i.uv, radius);
                texA *= i.color.a;                      // respect SpriteRenderer alpha
                clip(texA - _AlphaCutoff);

                // Dissolve toward the cast tip, darken at the contact end.
                float fade = 1.0 - smoothstep(0.2, 1.0, h01) * _TipFade;
                float contact = 1.0 - h01;
                fade *= 1.0 + _ContactBoost * contact * contact;

                half a = saturate(texA * _ShadowColor.a * _Opacity * fade);
                half3 rgb = _ShadowColor.rgb * a;       // premultiplied alpha
                return half4(rgb, a);
            }
        ENDHLSL
        }
    }
}

// GrassEdge.shader
// Built-in render pipeline.
// Companion to GrassFill — designed for the SpriteShape *edge* strip.
//
// The SpriteShape edge is a flat quad strip that looks unnaturally rigid.
// _Droop offsets vertices downward (in object space) proportional to their
// V texcoord (0 = top edge seam, 1 = bottom of the strip).  The result is
// a gentle curve that makes the grass fronds appear to hang and overhang
// the terrain edge rather than sitting on a flat plane.
//
// All other layers (detail, variation, wind) match GrassFill so both
// materials can share the same textures and look cohesive.

Shader "Custom/GrassEdge"
{
    Properties
    {
        _MainTex            ("Base Texture (can be white)",     2D)     = "white" {}
        _Color              ("Base Tint",                       Color)  = (0.35, 0.72, 0.28, 1)

        [Header(Droop)]
        _Droop              ("Droop Amount",                    Float)  = 0.15
        _DroopStart         ("Droop Start (UV)",               Range(0,1)) = 0.2

        [Header(Detail Overlay)]
        _DetailTex          ("Detail Texture (grass/noise)",    2D)     = "white" {}
        _DetailScale        ("Detail World Tile Scale",         Float)  = 2.0
        _DetailStrength     ("Detail Blend Strength",           Range(0,1)) = 0.45

        [Header(Colour Variation)]
        _VariationTex       ("Variation Noise (greyscale)",     2D)     = "gray" {}
        _VariationScale     ("Variation World Tile Scale",      Float)  = 6.0
        _VariationStrength  ("Variation Strength",              Range(0,0.4)) = 0.12
        _VariationDark      ("Variation Dark Tint",             Color)  = (0.2, 0.4, 0.1, 1)
        _VariationLight     ("Variation Light Tint",            Color)  = (0.6, 0.85, 0.3, 1)

        [Header(Wind)]
        _WindSpeed          ("Wind Speed",                      Float)  = 0.4
        _WindStrength       ("Wind UV Distort Strength",        Float)  = 0.015
        _WindDirection      ("Wind Direction (XZ)",             Vector) = (1, 0, 0, 0)
    }

    SubShader
    {
        Tags
        {
            "Queue"           = "Transparent"
            "RenderType"      = "Transparent"
            "IgnoreProjector" = "True"
            "PreviewType"     = "Plane"
        }

        Cull Off
        Lighting Off
        ZWrite Off
        Blend SrcAlpha OneMinusSrcAlpha

        Pass
        {
            CGPROGRAM
            #pragma vertex   vert
            #pragma fragment frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float4    _MainTex_ST;
            fixed4    _Color;

            float     _Droop;
            float     _DroopStart;

            sampler2D _DetailTex;
            float     _DetailScale;
            float     _DetailStrength;

            sampler2D _VariationTex;
            float     _VariationScale;
            float     _VariationStrength;
            fixed4    _VariationDark;
            fixed4    _VariationLight;

            float     _WindSpeed;
            float     _WindStrength;
            float4    _WindDirection;

            struct appdata_t
            {
                float4 vertex   : POSITION;
                float4 color    : COLOR;
                float2 texcoord : TEXCOORD0;
            };

            struct v2f
            {
                float4 vertex    : SV_POSITION;
                fixed4 color     : COLOR;
                float2 baseUV    : TEXCOORD0;
                float2 worldXZ   : TEXCOORD1;
            };

            v2f vert(appdata_t v)
            {
                // --- Droop ---
                // SpriteShape edge geometry only has vertices at UV.y = 0 (top seam)
                // and UV.y = 1 (bottom frond tip) — no intermediate rows.
                // A UV threshold would always snap, so _DroopStart instead scales
                // how far the bottom tip drops: 0 = full droop, 1 = no droop.
                // This gives a smooth, continuous change to the tip position.
                float droopFactor = saturate(v.texcoord.y) * saturate(1.0 - _DroopStart);

                float3 worldPos = mul(unity_ObjectToWorld, v.vertex).xyz;
                worldPos.y -= _Droop * droopFactor;

                v2f o;
                o.vertex  = mul(UNITY_MATRIX_VP, float4(worldPos, 1.0));
                o.color   = v.color * _Color;
                o.baseUV  = TRANSFORM_TEX(v.texcoord, _MainTex);
                o.worldXZ = worldPos.xz;

                return o;
            }

            fixed4 frag(v2f i) : SV_Target
            {
                // --- Base ---
                fixed4 base = tex2D(_MainTex, i.baseUV) * i.color;

                // --- Wind drift (applied to detail UVs only) ---
                float2 windDir    = normalize(_WindDirection.xz + float2(0.001, 0));
                float  windDrift  = _Time.y * _WindSpeed;
                float2 windOffset = windDir * windDrift * _WindStrength
                                  + sin(_Time.y * _WindSpeed * 0.7 + i.worldXZ.x * 0.5) * _WindStrength * float2(0.5, 0.5);

                // --- Detail overlay (world-space tiled) ---
                float2 detailUV  = i.worldXZ / _DetailScale + windOffset;
                fixed4 detail    = tex2D(_DetailTex, detailUV);
                fixed3 withDetail = lerp(base.rgb, base.rgb * detail.rgb * 2.0, _DetailStrength);

                // --- Colour variation (large-scale world-space noise) ---
                float2 varUV     = i.worldXZ / _VariationScale;
                float  varNoise  = tex2D(_VariationTex, varUV).r;
                fixed3 varColour = lerp(_VariationDark.rgb, _VariationLight.rgb, varNoise);
                fixed3 varied    = lerp(withDetail, withDetail * varColour, _VariationStrength);

                return fixed4(varied, base.a);
            }
            ENDCG
        }
    }

    Fallback "Sprites/Default"
}

